@GameTestHolder("psychedelicrafttests") @PrefixGameTestTemplate(false)
public final class DealerWorkGameTests {
    static final BlockPos TABLE=new BlockPos(5,2,6),CROP=new BlockPos(6,2,7);
    static void check(boolean value,String text){if(!value)throw new GameTestAssertException(text);}
    static DryingTableBlockEntity table(GameTestHelper h){h.setBlock(TABLE,PSBlocks.DRYING_TABLE.get());return (DryingTableBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(TABLE));}
    static Villager dealer(GameTestHelper h){var level=h.getLevel();level.setDayTime(3000);var v=EntityType.VILLAGER.create(level);v.setVillagerData(v.getVillagerData().setProfession(PSTradeOffers.DRUG_DEALER.get()));v.setNoAi(true);v.setPos(net.minecraft.world.phys.Vec3.atBottomCenterOf(h.absolutePos(CROP)));level.addFreshEntity(v);v.getBrain().setMemory(MemoryModuleType.JOB_SITE,GlobalPos.of(level.dimension(),h.absolutePos(TABLE)));v.getBrain().setMemory(MemoryModuleType.SECONDARY_JOB_SITE,List.of(GlobalPos.of(level.dimension(),h.absolutePos(CROP.below()))));v.getBrain().eraseMemory(MemoryModuleType.LOOK_TARGET);v.getBrain().eraseMemory(MemoryModuleType.WALK_TARGET);return v;}
    static void farmland(GameTestHelper h){h.setBlock(CROP.below(),Blocks.FARMLAND.defaultBlockState().setValue(FarmBlock.MOISTURE,7));}
    static List<ItemEntity> drops(GameTestHelper h){return h.getLevel().getEntitiesOfClass(ItemEntity.class,new net.minecraft.world.phys.AABB(h.absolutePos(CROP)).inflate(3));}
    static boolean start(Behavior<Villager> task,GameTestHelper h,Villager v){for(int i=0;i<128;i++)if(task.tryStart(h.getLevel(),v,h.getLevel().getGameTime()))return true;return false;}
    @GameTest(template="dealer_work",batch="dealer_work") public static void nativeBatchUsesExactlyNineAcrossSplitStacksAndPreservesUnrelatedItems(GameTestHelper h){
        var table=table(h);var inventory=new SimpleContainer(8);var first=new ItemStack(PSItems.CANNABIS_LEAF.get(),4);first.setHoverName(Component.literal("first crop"));inventory.setItem(0,first);inventory.setItem(1,new ItemStack(PSItems.CANNABIS_LEAF.get(),7));inventory.setItem(2,new ItemStack(Items.APPLE,12));
        check(DealerBehaviors.loadBatch(h.getLevel(),inventory,table),"registered drying recipe loads a complete batch");check(inventory.countItem(PSItems.CANNABIS_LEAF.get())==2&&inventory.countItem(Items.APPLE)==12,"exactly nine matching materials are consumed and unrelated inventory is retained");
        for(int i=1;i<=9;i++)check(table.getItem(i).is(PSItems.CANNABIS_LEAF.get())&&table.getItem(i).getCount()==1,"all nine real table input slots receive one item");check(table.getItem(1).getHoverName().getString().equals("first crop"),"item data survives inventory-to-table transfer");check(h.getLevel().getRecipeManager().getRecipeFor(PSRecipes.DRYING_TYPE.get(),table,h.getLevel()).isPresent(),"the native drying processor recognizes the loaded batch");h.succeed();
    }
    @GameTest(template="dealer_work",batch="dealer_work") public static void incompleteMixedOrOccupiedBatchesNeverConsumeOrOverwrite(GameTestHelper h){
        var table=table(h);var inventory=new SimpleContainer(8);inventory.setItem(0,new ItemStack(PSItems.CANNABIS_LEAF.get(),8));check(!DealerBehaviors.loadBatch(h.getLevel(),inventory,table)&&inventory.countItem(PSItems.CANNABIS_LEAF.get())==8&&table.isEmpty(),"eight inputs remain untouched");inventory.setItem(0,new ItemStack(PSItems.CANNABIS_LEAF.get(),4));inventory.setItem(1,new ItemStack(PSItems.COCA_LEAVES.get(),5));check(!DealerBehaviors.loadBatch(h.getLevel(),inventory,table)&&table.isEmpty(),"nine total items across two recipes cannot form a batch");inventory.setItem(0,new ItemStack(PSItems.CANNABIS_LEAF.get(),20));table.setItem(1,new ItemStack(Items.APPLE));check(!DealerBehaviors.loadBatch(h.getLevel(),inventory,table)&&table.getItem(1).is(Items.APPLE)&&inventory.countItem(PSItems.CANNABIS_LEAF.get())==20,"existing unfinished input is never overwritten");table.clearContent();table.setItem(0,new ItemStack(Items.BREAD,3));check(!DealerBehaviors.loadBatch(h.getLevel(),inventory,table)&&table.getItem(0).getCount()==3,"finished output also blocks insertion");h.succeed();
    }
    @GameTest(template="dealer_work",batch="dealer_work",setupTicks=310) public static void nativeWorkCollectsOnlyOutputRestocksAndRetainsPlayerInputs(GameTestHelper h){
        var table=table(h);var v=dealer(h);v.setPos(h.absolutePos(TABLE).getCenter().add(0,0,1));table.setItem(0,new ItemStack(PSItems.DRIED_CANNABIS_LEAF.get(),9));table.setItem(1,new ItemStack(Items.APPLE));v.getInventory().setItem(0,new ItemStack(PSItems.CANNABIS_LEAF.get(),18));var offer=v.getOffers().get(0);offer.increaseUses();var work=new DealerBehaviors.Work();check(start(work,h,v),"native WorkAtPoi starts at the remembered drying table");check(v.getInventory().countItem(PSItems.DRIED_CANNABIS_LEAF.get())==9&&table.getItem(0).isEmpty()&&table.getItem(1).is(Items.APPLE)&&v.getInventory().countItem(PSItems.CANNABIS_LEAF.get())==18,"only output is collected; unfinished player input survives and blocks loading");check(offer.getUses()==0&&v.getBrain().hasMemoryValue(MemoryModuleType.LAST_WORKED_AT_POI),"native stock restock and work-time memory run through the real callback");work.doStop(h.getLevel(),v,h.getLevel().getGameTime());v.discard();h.succeed();
    }
    @GameTest(template="dealer_work",batch="dealer_work") public static void fullInventoryDropsExactlyOneOverflowAndCannotRepeatCollection(GameTestHelper h){
        var table=table(h);var v=dealer(h);for(int i=0;i<8;i++)v.getInventory().setItem(i,new ItemStack(Items.STONE,64));table.setItem(0,new ItemStack(PSItems.DRIED_COCA_LEAVES.get(),9));DealerBehaviors.workTable(h.getLevel(),v,table);DealerBehaviors.workTable(h.getLevel(),v,table);var drops=drops(h);check(table.isEmpty()&&drops.size()==1&&drops.get(0).getItem().is(PSItems.DRIED_COCA_LEAVES.get())&&drops.get(0).getItem().getCount()==9,"full inventory output="+table.getItem(0)+" drops="+drops.stream().map(e->e.getItem().toString()).toList());drops.forEach(ItemEntity::discard);v.discard();h.succeed();
    }
    @GameTest(template="dealer_work",batch="dealer_work") public static void cancelledOverflowRetainsOnlyUnstoredOutputAndPreventsNewBatch(GameTestHelper h){
        var table=table(h);var v=dealer(h);for(int i=0;i<8;i++)v.getInventory().setItem(i,new ItemStack(Items.STONE,64));v.getInventory().setItem(0,new ItemStack(PSItems.DRIED_COCA_LEAVES.get(),62));table.setItem(0,new ItemStack(PSItems.DRIED_COCA_LEAVES.get(),9));Object cancel=new Object(){@net.minecraftforge.eventbus.api.SubscribeEvent public void cancelDealerOverflowJoin(EntityJoinLevelEvent e){if(e.getEntity() instanceof ItemEntity item&&item.distanceToSqr(v)<16)e.setCanceled(true);}};MinecraftForge.EVENT_BUS.register(cancel);
        try{DealerBehaviors.workTable(h.getLevel(),v,table);}finally{MinecraftForge.EVENT_BUS.unregister(cancel);}check(v.getInventory().countItem(PSItems.DRIED_COCA_LEAVES.get())==64&&table.getItem(0).getCount()==7&&drops(h).isEmpty(),"two stored plus seven retained equals nine when native drop spawning is cancelled");v.discard();h.succeed();
    }
    @GameTest(template="dealer_work",batch="dealer_work") public static void nativeCapturedDropsAreDeliveredWithoutRestoringDuplicateOutput(GameTestHelper h){
        var table=table(h);var v=dealer(h);for(int i=0;i<8;i++)v.getInventory().setItem(i,new ItemStack(Items.STONE,64));table.setItem(0,new ItemStack(PSItems.DRIED_COCA_LEAVES.get(),9));var captured=new ArrayList<ItemEntity>();var previous=v.captureDrops(captured);try{DealerBehaviors.workTable(h.getLevel(),v,table);}finally{v.captureDrops(previous);}check(table.isEmpty()&&captured.size()==1&&captured.get(0).getItem().getCount()==9&&drops(h).isEmpty(),"native captured drop owns the result without a world spawn or duplicate in the table");v.discard();h.succeed();
    }
    @GameTest(template="dealer_work",batch="dealer_work") public static void acceptedMaturityUsesCoffeaUpperAgeAndRetainsNativeWheatRules(GameTestHelper h){
        var coffea=PSBlocks.COFFEA.get().defaultBlockState().setValue(TobaccoPlantBlock.TOP,true).setValue(BlockStateProperties.AGE_7,3);check(DealerBehaviors.mature(coffea)&&!DealerBehaviors.mature(coffea.setValue(TobaccoPlantBlock.TOP,false))&&!DealerBehaviors.mature(coffea.setValue(BlockStateProperties.AGE_7,2)),"age-three upper coffea is mature while lower/young stages are not");check(DealerBehaviors.mature(PSBlocks.CANNABIS.get().defaultBlockState().setValue(BlockStateProperties.AGE_15,15))&&DealerBehaviors.mature(Blocks.WHEAT.defaultBlockState().setValue(CropBlock.AGE,7))&&!DealerBehaviors.mature(Blocks.WHEAT.defaultBlockState()),"accepted tall crop maturity and native wheat maturity coexist");h.succeed();
    }
    @GameTest(template="dealer_work",batch="dealer_work") public static void nativeHarvestPlantsOnFarmlandSpendsOneSeedAndReplantsAfterHarvest(GameTestHelper h){
        table(h);farmland(h);h.setBlock(CROP.above(),Blocks.SEA_LANTERN);h.runAtTickTime(5,()->{var v=dealer(h);v.getInventory().setItem(0,new ItemStack(PSItems.COCA_SEEDS.get(),3));var harvest=new DealerBehaviors.Harvest();check(harvest.tryStart(h.getLevel(),v,h.getLevel().getGameTime()),"native harvest starts above the actual fixture floor with farmland and secondary job memory");long time=h.getLevel().getGameTime();harvest.tickOrStop(h.getLevel(),v,time+1);check(h.getLevel().getBlockState(h.absolutePos(CROP)).is(PSBlocks.COCA.get())&&v.getInventory().countItem(PSItems.COCA_SEEDS.get())==2,"native planting: state="+h.getLevel().getBlockState(h.absolutePos(CROP))+" seeds="+v.getInventory().countItem(PSItems.COCA_SEEDS.get())+" survives="+PSBlocks.COCA.get().defaultBlockState().canSurvive(h.getLevel(),h.absolutePos(CROP))+" target="+v.getBrain().getMemory(MemoryModuleType.WALK_TARGET).map(target->target.getTarget().currentBlockPosition()));harvest.doStop(h.getLevel(),v,time+2);
        var mature=PSBlocks.COCA.get().defaultBlockState().setValue(PSBlocks.COCA.get().getAgeProperty(),12);h.setBlock(CROP,mature);v.getBrain().eraseMemory(MemoryModuleType.LOOK_TARGET);v.getBrain().eraseMemory(MemoryModuleType.WALK_TARGET);harvest=new DealerBehaviors.Harvest();check(harvest.tryStart(h.getLevel(),v,time),"mature coca is selected");harvest.tickOrStop(h.getLevel(),v,time+1);check(h.getLevel().getBlockState(h.absolutePos(CROP)).isAir(),"native block destruction harvests the crop with real loot");harvest.tickOrStop(h.getLevel(),v,time+2);check(h.getLevel().getBlockState(h.absolutePos(CROP)).is(PSBlocks.COCA.get())&&v.getInventory().countItem(PSItems.COCA_SEEDS.get())==1,"following native tick replants without charging twice");harvest.doStop(h.getLevel(),v,time+3);drops(h).forEach(ItemEntity::discard);v.discard();h.succeed();
        });
    }
    @GameTest(template="dealer_work",batch="dealer_work") public static void cropWorkHonorsMobGriefingHoursTradingAndRealSoil(GameTestHelper h){
        table(h);farmland(h);var v=dealer(h);v.getInventory().setItem(0,new ItemStack(PSItems.COCA_SEEDS.get(),3));var rule=h.getLevel().getGameRules().getRule(GameRules.RULE_MOBGRIEFING);boolean before=rule.get();rule.set(false,h.getLevel().getServer());try{check(!new DealerBehaviors.Harvest().tryStart(h.getLevel(),v,h.getLevel().getGameTime()),"native mobGriefing prevents crop work");}finally{rule.set(before,h.getLevel().getServer());}
        h.getLevel().setDayTime(12000);check(!new DealerBehaviors.Harvest().tryStart(h.getLevel(),v,h.getLevel().getGameTime()),"accepted work hours exclude evening");h.getLevel().setDayTime(3000);v.setTradingPlayer(h.makeMockPlayer());check(!new DealerBehaviors.Harvest().tryStart(h.getLevel(),v,h.getLevel().getGameTime()),"trading prevents crop work");v.setTradingPlayer(null);h.setBlock(CROP.below(),Blocks.STONE);check(!new DealerBehaviors.Harvest().tryStart(h.getLevel(),v,h.getLevel().getGameTime())&&v.getInventory().countItem(PSItems.COCA_SEEDS.get())==3,"stone supports neither farmer crop planting nor seed consumption");v.discard();h.succeed();
    }
    @GameTest(template="dealer_work",batch="dealer_work") public static void nativeBonemealUsesRealInventoryBudgetTimingAndRestoresHeldPreview(GameTestHelper h){
        table(h);farmland(h);h.setBlock(CROP,PSBlocks.CANNABIS.get());var v=dealer(h);v.getInventory().setItem(0,new ItemStack(Items.BONE_MEAL,5));v.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.BREAD));var bone=new DealerBehaviors.Bonemeal();long time=h.getLevel().getGameTime();check(bone.tryStart(h.getLevel(),v,time)&&v.getMainHandItem().is(Items.BONE_MEAL),"native equipment displays the work item");bone.tickOrStop(h.getLevel(),v,time+1);int age=h.getLevel().getBlockState(h.absolutePos(CROP)).getValue(BlockStateProperties.AGE_15);check(age>=1&&v.getInventory().countItem(Items.BONE_MEAL)==4,"native BoneMealItem grows the crop and consumes exactly one");bone.tickOrStop(h.getLevel(),v,time+39);check(v.getInventory().countItem(Items.BONE_MEAL)==4,"40-tick application interval prevents a second early charge");bone.tickOrStop(h.getLevel(),v,time+41);check(v.getInventory().countItem(Items.BONE_MEAL)==3,"second application is allowed after the interval");bone.tickOrStop(h.getLevel(),v,time+62);check(v.getMainHandItem().is(Items.BREAD)&&!bone.tryStart(h.getLevel(),v,time+63),"session cleanup restores the previous native preview and applies the 160-tick cooldown");v.discard();h.succeed();
    }
    @GameTest(template="dealer_work",batch="dealer_work") public static void nativeNoAiTickStopsBonemealWithoutEatingOrDroppingDisplayItem(GameTestHelper h){
        table(h);farmland(h);h.setBlock(CROP,PSBlocks.CANNABIS.get());var v=dealer(h);v.getInventory().setItem(0,new ItemStack(Items.BONE_MEAL,4));var bone=new DealerBehaviors.Bonemeal();v.getBrain().addActivity(Activity.CORE,ImmutableList.of(Pair.of(7,bone)));check(bone.tryStart(h.getLevel(),v,h.getLevel().getGameTime()),"registered native behavior starts");MinecraftForge.EVENT_BUS.post(new LivingEvent.LivingTickEvent(v));check(bone.getStatus()==Behavior.Status.STOPPED&&v.getMainHandItem().isEmpty()&&v.getInventory().countItem(Items.BONE_MEAL)==4&&drops(h).isEmpty(),"NoAI cleanup stops the real registered work and removes only its visual equipment");v.discard();h.succeed();
    }
    @GameTest(template="dealer_work",batch="dealer_work") public static void activeWorkDisplayReloadAndDeathRestoreRealEquipmentWithoutCreatingMeal(GameTestHelper h){
        table(h);farmland(h);h.setBlock(CROP,PSBlocks.CANNABIS.get());var v=dealer(h);v.getInventory().setItem(0,new ItemStack(Items.BONE_MEAL,4));v.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.BREAD));v.setDropChance(EquipmentSlot.MAINHAND,2);
        var bone=new DealerBehaviors.Bonemeal();check(bone.tryStart(h.getLevel(),v,h.getLevel().getGameTime()),"work starts before saving");check(((ivorius.psychedelicraft.mixin.MobEquipmentAccessor)v).psychedelicraft$getEquipmentDropChance(EquipmentSlot.MAINHAND)==0,"displayed bone meal cannot be native equipment loot");
        var saved=new CompoundTag();v.save(saved);bone.doStop(h.getLevel(),v,h.getLevel().getGameTime());v.discard();var restored=(Villager)EntityType.loadEntityRecursive(saved,h.getLevel(),java.util.function.Function.identity());check(h.getLevel().addFreshEntity(restored),"saved working villager rejoins the real level");check(restored.getMainHandItem().is(Items.BREAD)&&restored.getInventory().countItem(Items.BONE_MEAL)==4&&((ivorius.psychedelicraft.mixin.MobEquipmentAccessor)restored).psychedelicraft$getEquipmentDropChance(EquipmentSlot.MAINHAND)==2,"native entity join restores the real held stack and exact drop chance without inventing meal");
        restored.getBrain().eraseMemory(MemoryModuleType.LOOK_TARGET);restored.getBrain().eraseMemory(MemoryModuleType.WALK_TARGET);bone=new DealerBehaviors.Bonemeal();check(bone.tryStart(h.getLevel(),restored,h.getLevel().getGameTime()),"restored villager can start another real work session");restored.getInventory().clearContent();restored.hurt(restored.damageSources().genericKill(),Float.MAX_VALUE);var dropped=drops(h);check(dropped.stream().noneMatch(item->item.getItem().is(Items.BONE_MEAL))&&dropped.stream().filter(item->item.getItem().is(Items.BREAD)).mapToInt(item->item.getItem().getCount()).sum()==1,"native death drops only the genuine guaranteed equipment and no displayed meal");dropped.forEach(ItemEntity::discard);restored.discard();h.succeed();
    }
    @GameTest(template="dealer_work",batch="dealer_work") public static void nativeProfessionPackageIncludesDealerWorkAndKeepsFarmerAndSnifferPickupNative(GameTestHelper h){
        check(VillagerGoalPackages.getWorkPackage(PSTradeOffers.DRUG_DEALER.get(),.5F).stream().anyMatch(p->p.getSecond() instanceof DealerBehaviors.WorkCycle),"actual native profession package includes the custom weighted work cycle");check(VillagerGoalPackages.getWorkPackage(VillagerProfession.FARMER,.5F).stream().noneMatch(p->p.getSecond() instanceof DealerBehaviors.WorkCycle),"vanilla farmer package remains native");var v=dealer(h);check(v.wantsToPickUp(new ItemStack(PSItems.COFFEA_CHERRIES.get()))&&v.wantsToPickUp(new ItemStack(PSItems.CANNABIS_LEAF.get()))&&v.wantsToPickUp(new ItemStack(Items.BONE_MEAL)),"native dealer requested-items pickup includes seeds, materials and meal");v.setVillagerData(v.getVillagerData().setProfession(VillagerProfession.NONE));check(v.wantsToPickUp(new ItemStack(Items.TORCHFLOWER_SEEDS))&&v.wantsToPickUp(new ItemStack(Items.PITCHER_POD)),"native wanted items preserve the accepted global Sniffer-seed pickup interaction");v.discard();h.succeed();
    }
}
